            <div><label class="form-label" for="club-search">Managed club</label><div class="catalog-picker" data-catalog-picker="club"><input type="hidden" id="career-club" name="club_id" value="<?= Html::encode($form->clubId) ?>"><div class="catalog-picker__control"><input class="form-control catalog-picker__input" id="club-search" type="text" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="club-results" autocomplete="off" placeholder="Search clubs" value="<?= Html::encode($selectedClub === null ? '' : $selectedClub->name) ?>"><button class="catalog-picker__clear" type="button" aria-label="Clear club selection" <?= $selectedClub === null ? 'hidden' : '' ?>>×</button></div><div class="catalog-picker__results" id="club-results" role="listbox" hidden><?php foreach ($clubs as $club): ?><button class="catalog-picker__option" type="button" role="option" data-value="<?= Html::encode($club->id->toString()) ?>" data-label="<?= Html::encode($club->name) ?>" data-league-id="<?= Html::encode($club->defaultLeagueId?->toString() ?? '') ?>"><img src="<?= Html::encode($club->logoUrl ?? '') ?>" alt=""><span><?= Html::encode($club->name) ?><small><?= Html::encode($club->country) ?></small></span></button><?php endforeach ?><p class="catalog-picker__empty" hidden>No matching clubs in this league.</p></div></div><?php foreach ($form->errorsFor('club_id') as $error): ?><div class="invalid-feedback d-block"><?= Html::encode($error) ?></div><?php endforeach ?><p class="form-text">Choose any club. Its default league is suggested only when no league is selected.</p></div>
