<script>
(() => { const createPicker = (root, filter = () => true) => { const input = root.querySelector('.catalog-picker__input'), hidden = root.querySelector('input[type=hidden]'), clear = root.querySelector('.catalog-picker__clear'), results = root.querySelector('.catalog-picker__results'), options = [...root.querySelectorAll('.catalog-picker__option')], empty = root.querySelector('.catalog-picker__empty'); let active = -1; const visible = () => options.filter(option => !option.hidden); const render = () => { const query = input.value.trim().toLocaleLowerCase(); options.forEach(option => { option.hidden = !filter(option) || !option.dataset.label.toLocaleLowerCase().includes(query); }); empty.hidden = visible().length !== 0; active = -1; }; const open = () => { if (input.disabled) return; results.hidden = false; input.setAttribute('aria-expanded', 'true'); render(); }; const close = () => { results.hidden = true; input.setAttribute('aria-expanded', 'false'); active = -1; }; const select = option => { hidden.value = option.dataset.value; input.value = option.dataset.label; clear.hidden = false; root.dispatchEvent(new CustomEvent('picker:select', { bubbles: true, detail: option })); close(); }; input.addEventListener('focus', open); input.addEventListener('input', () => { if (hidden.value !== '') { hidden.value = ''; clear.hidden = true; root.dispatchEvent(new CustomEvent('picker:clear', { bubbles: true })); } open(); }); input.addEventListener('keydown', event => { const items = visible(); if (event.key === 'ArrowDown' || event.key === 'ArrowUp') { event.preventDefault(); open(); active = Math.max(0, Math.min(items.length - 1, active + (event.key === 'ArrowDown' ? 1 : -1))); items.forEach((item, index) => item.classList.toggle('is-active', index === active)); items[active]?.scrollIntoView({ block: 'nearest' }); } if (event.key === 'Enter' && active >= 0) { event.preventDefault(); select(items[active]); } if (event.key === 'Escape') close(); }); options.forEach(option => option.addEventListener('click', () => select(option))); clear.addEventListener('click', () => { hidden.value = ''; input.value = ''; clear.hidden = true; render(); input.focus(); root.dispatchEvent(new CustomEvent('picker:clear', { bubbles: true })); }); document.addEventListener('click', event => { if (!root.contains(event.target)) close(); }); return { input, hidden, render, reset: (placeholder) => { hidden.value = ''; input.value = ''; input.placeholder = placeholder; clear.hidden = true; } }; }; const leagueRoot = document.querySelector('[data-catalog-picker=league]'), clubRoot = document.querySelector('[data-catalog-picker=club]'), start = document.querySelector('#starts-on'), end = document.querySelector('#ends-on'); let league; const club = createPicker(clubRoot); league = createPicker(leagueRoot); const applyDates = option => { const sm = +option.dataset.startMonth, sd = +option.dataset.startDay, y = 2025, pad = n => String(n).padStart(2, '0'); start.value = `${y}-${pad(sm)}-${pad(sd)}`; const ey = (+option.dataset.endMonth < sm || (+option.dataset.endMonth === sm && +option.dataset.endDay < sd)) ? y + 1 : y; end.value = `${ey}-${pad(+option.dataset.endMonth)}-${pad(+option.dataset.endDay)}`; }; leagueRoot.addEventListener('picker:select', event => { club.render(); applyDates(event.detail); }); leagueRoot.addEventListener('picker:clear', () => { club.render(); }); clubRoot.addEventListener('picker:select', event => { if (league.hidden.value !== '') return; const suggestedLeague = [...leagueRoot.querySelectorAll('.catalog-picker__option')].find(option => option.dataset.value === event.detail.dataset.leagueId); suggestedLeague?.click(); }); club.render(); })();
</script>
